UPDATE dtb_customer
SET email=JSON_VALUE(CAST(:customer AS JSON), '$.email'), password=JSON_VALUE(CAST(:customer AS JSON), '$.passwordHash'), name01=JSON_VALUE(CAST(:customer AS JSON), '$.name01'), name02=JSON_VALUE(CAST(:customer AS JSON), '$.name02'), kana01=JSON_VALUE(CAST(:customer AS JSON), '$.kana01'), kana02=JSON_VALUE(CAST(:customer AS JSON), '$.kana02'), company_name=JSON_VALUE(CAST(:customer AS JSON), '$.companyName'), phone_number=JSON_VALUE(CAST(:customer AS JSON), '$.phoneNumber'), postal_code=JSON_VALUE(CAST(:customer AS JSON), '$.postalCode'), pref_id=CAST(JSON_VALUE(CAST(:customer AS JSON), '$.pref') AS UNSIGNED), addr01=JSON_VALUE(CAST(:customer AS JSON), '$.addr01'), addr02=JSON_VALUE(CAST(:customer AS JSON), '$.addr02'), birth=JSON_VALUE(CAST(:customer AS JSON), '$.birth'), sex_id=CAST(JSON_VALUE(CAST(:customer AS JSON), '$.sex') AS UNSIGNED), job_id=CAST(JSON_VALUE(CAST(:customer AS JSON), '$.job') AS UNSIGNED), customer_status_id=CAST(JSON_VALUE(CAST(:customer AS JSON), '$.customerStatus') AS UNSIGNED), secret_key=COALESCE(JSON_VALUE(CAST(:customer AS JSON), '$.secretKey'), ''), point=CAST(JSON_VALUE(CAST(:customer AS JSON), '$.initialPoint') AS SIGNED), update_date=NOW()
WHERE JSON_VALUE(CAST(:customer AS JSON), '$.customerId') REGEXP '^[0-9]+$' AND id=CAST(JSON_VALUE(CAST(:customer AS JSON), '$.customerId') AS UNSIGNED)
